// Core closed-form formulas
const sumTo = n => n*(n+1)/2;
const sumSquares = n => n*(n+1)*(2*n+1)/6;
const geoSum = (a,r,n) => r===1 ? a*n : a*(Math.pow(r,n)-1)/(r-1);

// Count multiples of k in [l, r]
const countMultiples = (l,r,k) => Math.floor(r/k)-Math.floor((l-1)/k);

// Integer ceiling without float division
const ceilDiv = (n,k) => Math.floor((n+k-1)/k);

// Sum of all subarray sums: arr[i] contributes to (i+1)*(n-i) subarrays
function subarraySum(arr) {
  const n=arr.length;
  let total=0;
  for (let i=0;i<n;i++) total+=arr[i]*(i+1)*(n-i);
  return total;
}

// Coordinate rotation: (x,y) -> (x+y, x-y)
// Max Chebyshev distance = max range in either transformed coordinate
function maxChebyshevDistance(points) {
  let minU=Infinity,maxU=-Infinity,minV=Infinity,maxV=-Infinity;
  for (const [x,y] of points) {
    const u=x+y, v=x-y;
    minU=Math.min(minU,u); maxU=Math.max(maxU,u);
    minV=Math.min(minV,v); maxV=Math.max(maxV,v);
  }
  return Math.max(maxU-minU, maxV-minV);
}
